1: #!/usr/bin/env node
2: /**
3:  * zentao-resolve.mjs — 禅道 Bug 回写固定序列生成器
4:  *
5:  * 用途：把「开事务 → UPDATE zt_bug → INSERT zt_action → 复核 → commit」封成固定脚本，
6:  *       参数只暴露 bugId 和 comment，杜绝漏 connection_name / 列数不匹配等复发错误。
7:  *
8:  * 用法：
9:  *   node zentao-resolve.mjs <bugId> <commentHTML>
10:  * 输出：可直接照抄执行的 mcp_gateway 调用序列（JSON），以及各步的预期核验点。
11:  *
12:  * 约束（与 DBX.md 一致）：
13:  *   - 只对新禅道库（connection_name: "新禅道"）写；每次调用都必须带 connection_name。
14:  *   - zt_action 严格 14 列，files 用 NULL 占位；`read` 必须反引号。
15:  *   - comment 走 HTML，写根因 + 修复 + 验证证据。
16:  */
17: 
18: const bugId = Number(process.argv[2]);
19: const comment = process.argv[3] ?? "";
20: 
21: if (!Number.isInteger(bugId) || bugId <= 0) {
22:   console.error("用法: node zentao-resolve.mjs <bugId> <commentHTML>  （bugId 必须为正整数）");
23:   process.exit(1);
24: }
25: if (!comment.trim()) {
26:   console.error("comment 不能为空：需要根因 + 修复 + 验证证据（HTML）");
27:   process.exit(1);
28: }
29: 
30: const CONN = "新禅道";
31: const ACTOR = "tiany";
32: const esc = (s) => s.replace(/'/g, "''");
33: 
34: const steps = [
35:   {
36:     name: "1) 查现状（拿 product/project/execution/openedBy）",
37:     sql:
38:       `SELECT id,status,assignedTo,openedBy,product,project,execution,resolution ` +
39:       `FROM zt_bug WHERE id=${bugId};`,
40:     verify: "记录 openedBy（回写 assignedTo 用）与 product/project/execution 原值",
41:   },
42:   {
43:     name: "2) 开事务 session",
44:     call: {
45:       server: "dbx",
46:       tool: "dbx_open_session",
47:       arguments: { connection_name: CONN, enable_transactions: true },
48:     },
49:     verify: "取返回的 session_id，后续所有事务内调用都带它 + connection_name",
50:   },
51:   {
52:     name: "3) begin",
53:     call: {
54:       server: "dbx",
55:       tool: "dbx_begin_transaction",
56:       arguments: { connection_name: CONN, session_id: "<session_id>" },
57:     },
58:     verify: "成功后再执行第 4/5 步",
59:   },
60:   {
61:     name: "4) UPDATE zt_bug → resolved",
62:     sql:
63:       `UPDATE zt_bug SET status='resolved', resolution='fixed', resolvedBuild='trunk', ` +
64:       `resolvedBy='${ACTOR}', resolvedDate=NOW(), assignedTo='<openedBy>', ` +
65:       `lastEditedBy='${ACTOR}', lastEditedDate=NOW() WHERE id=${bugId};`,
66:     verify: "affected rows = 1",
67:   },
68:   {
69:     name: "5) INSERT zt_action（14 列，files=NULL 占位）",
70:     sql:
71:       `INSERT INTO zt_action ` +
72:       `(objectType,objectID,product,project,execution,actor,action,date,comment,files,extra,\`read\`,efforted,vision) ` +
73:       `VALUES ('bug',${bugId},'<product>','<project>','<execution>','${ACTOR}','resolved',NOW(),` +
74:       `'${esc(comment)}',NULL,'fixed',0,0,'rnd');`,
75:     verify: "affected rows = 1；product/project/execution 用第 1 步查到的原值",
76:   },
77:   {
78:     name: "6) 事务内复核",
79:     sql:
80:       `SELECT status,resolution,resolvedBy,resolvedDate,assignedTo FROM zt_bug WHERE id=${bugId};\n` +
81:       `SELECT actor,action FROM zt_action WHERE objectType='bug' AND objectID=${bugId} ORDER BY id DESC;`,
82:     verify: "status=resolved / resolution=fixed / resolvedBy / assignedTo 均符合预期",
83:   },
84:   {
85:     name: "7) commit",
86:     call: {
87:       server: "dbx",
88:       tool: "dbx_commit_transaction",
89:       arguments: { connection_name: CONN, session_id: "<session_id>" },
90:     },
91:     verify: "返回 committed 即成功；不再做无 session 的第二次复核",
92:   },
93:   {
94:     name: "8) 关 session",
95:     call: {
96:       server: "dbx",
97:       tool: "dbx_close_session",
98:       arguments: { connection_name: CONN, session_id: "<session_id>" },
99:     },
100:     verify: "结束",
101:   },
102: ];
103: 
104: console.log(`# zt_bug ${bugId} 回写序列（connection_name=${CONN}，每步必带）\n`);
105: for (const s of steps) {
106:   console.log(`## ${s.name}`);
107:   if (s.call) {
108:     console.log("mcp_gateway " + JSON.stringify(s.call, null, 2));
109:   } else {
110:     const inTxn = /^[4-6]\)/.test(s.name);
111:     const arguments_ = { connection_name: CONN, sql: s.sql };
112:     if (inTxn) arguments_.session_id = "<session_id>";
113:     console.log(
114:       "mcp_gateway " +
115:         JSON.stringify(
116:           { server: "dbx", tool: "dbx_execute_query", arguments: arguments_ },
117:           null,
118:           2
119:         )
120:     );
121:   }
122:   console.log(`核验: ${s.verify}\n`);
123: }

